do $pub$
declare
  g constant uuid := '6db1b18e-cc36-4cb2-9db5-cb87b6d815fe';
  es_id constant uuid := '7fe7e772-3435-4260-bb96-ce41091ff8ea';
  j constant jsonb := $j$[
{"id":"7fe7e772-3435-4260-bb96-ce41091ff8ea","recipe_group_id":"6db1b18e-cc36-4cb2-9db5-cb87b6d815fe","language":"es","slug":"sopa-de-tomate","public_path":"/sopa-de-tomate","source_url":null,"title":"Sopa de tomate","excerpt":"Sopa de tomate casera y cremosa, con tomates maduros, cebolla, ajo y albahaca fresca. Para 4 personas, lista en 45 minutos.","summary":"La sopa de tomate se prepara sofriendo cebolla y ajo en aceite de oliva, cocinando los tomates maduros con caldo de verduras y triturando todo con albahaca hasta obtener una crema lisa. Se sirve caliente con hojas de albahaca y un hilo de aceite.\n\nLa sopa tarda 45 minutos entre preparación y cocción. Rinde 4 porciones.","category":"Sopas y cremas","difficulty":"Fácil","course":"Entrante","cuisine":"Internacional","prep_time_minutes":10,"cook_time_minutes":35,"total_time_minutes":45,"servings":4,"keywords":["sopa de tomate","receta de sopa de tomate","cómo hacer sopa de tomate","sopa de tomate casera","crema de tomate","sopa de tomate con albahaca","sopa de tomate natural"],"ingredients":[{"name":"tomates maduros","amount":"1","unit":"kg","group":"Para la sopa"},{"name":"cebolla","amount":"1","unit":"","group":"Para la sopa"},{"name":"dientes de ajo","amount":"3","unit":"","group":"Para la sopa"},{"name":"aceite de oliva","amount":"3","unit":"cucharada","group":"Para la sopa"},{"name":"caldo de verduras","amount":"500","unit":"ml","group":"Para la sopa"},{"name":"hojas de albahaca fresca","amount":"10","unit":"g","group":"Para la sopa"},{"name":"sal","amount":"1/2","unit":"cucharadita","group":"Para la sopa"},{"name":"pimienta negra molida","amount":"1","unit":"pizca","group":"Para la sopa"}],"steps":[{"title":"Prepara los ingredientes","content":"Lava 1 kg de tomates y córtalos en cuartos. Pica finamente 1 cebolla y 3 dientes de ajo.","image_url":"/recetas/sopa-de-tomate/paso-01.webp","image_alt":"Sopa de tomate: Prepara los ingredientes"},{"title":"Sofríe la cebolla y el ajo","content":"Calienta 2 cucharadas de aceite de oliva en una olla y sofríe la cebolla y el ajo 5 minutos a fuego medio, sin que se doren.","image_url":"/recetas/sopa-de-tomate/paso-02.webp","image_alt":"Sopa de tomate: Sofríe la cebolla y el ajo"},{"title":"Añade los tomates","content":"Incorpora los tomates y cocínalos 10 minutos, removiendo de vez en cuando, hasta que empiecen a deshacerse.","image_url":"/recetas/sopa-de-tomate/paso-03.webp","image_alt":"Sopa de tomate: Añade los tomates"},{"title":"Cuece con el caldo","content":"Vierte 500 ml de caldo de verduras y cuece 15 minutos a fuego medio.","image_url":"/recetas/sopa-de-tomate/paso-04.webp","image_alt":"Sopa de tomate: Cuece con el caldo"},{"title":"Añade la albahaca","content":"Añade 10 g de hojas de albahaca fresca y remueve; reserva unas hojas para servir.","image_url":"/recetas/sopa-de-tomate/paso-05.webp","image_alt":"Sopa de tomate: Añade la albahaca"},{"title":"Tritura la sopa","content":"Tritura con la batidora de mano hasta obtener una crema lisa.","image_url":"/recetas/sopa-de-tomate/paso-06.webp","image_alt":"Sopa de tomate: Tritura la sopa"},{"title":"Rectifica el sazón","content":"Prueba la sopa, añade 1/2 cucharadita de sal y 1 pizca de pimienta y tritura unos segundos más para integrarlas.","image_url":"/recetas/sopa-de-tomate/paso-07.webp","image_alt":"Sopa de tomate: Rectifica el sazón"},{"title":"Sirve","content":"Sirve caliente en platos hondos, con hojas de albahaca y un hilo con la cucharada de aceite de oliva restante.","image_url":"/recetas/sopa-de-tomate/paso-08.webp","image_alt":"Sopa de tomate: Sirve"}],"image_url":"/recetas/sopa-de-tomate/portada.webp","gallery":[{"url":"/recetas/sopa-de-tomate/portada.webp","alt":"Sopa de tomate"}],"notes":"Los tomates bien maduros dan una sopa más dulce y de color intenso; si están ácidos, añade una pizca de azúcar al rectificar. Para una textura más fina, pásala por un colador después de triturarla. Se conserva hasta 3 días en la nevera y se puede congelar hasta 3 meses. Al recalentarla, añade un poco de caldo si ha espesado.","nutrition":{"calories":160,"protein_g":3.0,"carbs_g":15,"fat_g":10.8,"sodium_mg":265,"serving_size":"1 porción (1/4 de la receta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 4 porciones. Se usan 1 kg de tomates, 150 g de cebolla, 9 g de ajo, 40,5 g de aceite de oliva, 500 ml de caldo de verduras y 10 g de albahaca. La sal y la pimienta añadidas no se cuentan.","note":"Estimación por porción. El caldo de verduras se calcula con valores aproximados de un caldo comercial; su sodio varía mucho según la marca.","inputs":[{"fdc_id":"170457","description":"Tomatoes, red, ripe, raw (1 kg de tomates)","grams":1000,"per100":{"calories":18,"protein_g":0.88,"carbs_g":3.89,"fat_g":0.2,"saturated_fat_g":0.028,"fiber_g":1.2,"sodium_mg":5}},{"fdc_id":"170000","description":"Onions, raw (1 cebolla ≈ 150 g)","grams":150,"per100":{"calories":40,"protein_g":1.1,"carbs_g":9.34,"fat_g":0.1,"saturated_fat_g":0.042,"fiber_g":1.7,"sodium_mg":4}},{"fdc_id":"169230","description":"Garlic, raw (3 dientes ≈ 9 g)","grams":9,"per100":{"calories":149,"protein_g":6.36,"carbs_g":33.06,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17}},{"fdc_id":"171413","description":"Oil, olive, salad or cooking (3 cucharadas ≈ 40,5 g)","grams":40.5,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":13.81,"fiber_g":0,"sodium_mg":2}},{"fdc_id":"proxy","description":"Vegetable broth, ready-to-serve — proxy, valores aproximados de un caldo comercial (500 ml ≈ 500 g)","grams":500,"per100":{"calories":5,"protein_g":0.1,"carbs_g":1.0,"fat_g":0.1,"saturated_fat_g":0,"fiber_g":0,"sodium_mg":200}},{"fdc_id":"172232","description":"Basil, fresh (10 g de hojas)","grams":10,"per100":{"calories":23,"protein_g":3.15,"carbs_g":2.65,"fat_g":0.64,"saturated_fat_g":0.041,"fiber_g":1.6,"sodium_mg":4}}]},"seo":{"title":"Sopa de tomate casera y cremosa | Manual de Cocina","description":"Sopa de tomate casera y cremosa, con tomates maduros, cebolla, ajo y albahaca fresca. Para 4 personas, lista en 45 minutos.","image_variants":["/recetas/sopa-de-tomate/portada-1x1.webp","/recetas/sopa-de-tomate/portada-4x3.webp","/recetas/sopa-de-tomate/portada-16x9.webp"],"faq":[{"q":"¿Puedo usar tomate de lata?","a":"Sí. Usa unos 800 g de tomate entero en lata con su jugo y reduce la cocción de los tomates a 5 minutos."},{"q":"¿Cómo hago la sopa más cremosa?","a":"Añade 100 ml de nata o leche al triturarla, o tritura con ella una papa pequeña cocida en el caldo."},{"q":"¿Se puede congelar la sopa de tomate?","a":"Sí, hasta 3 meses en un recipiente hermético. Descongélala en la nevera y recaliéntala a fuego suave."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"a614ee95-dc2a-55b6-8eb4-a16fc25d26da","recipe_group_id":"6db1b18e-cc36-4cb2-9db5-cb87b6d815fe","language":"de","slug":"tomatensuppe","public_path":"/de/tomatensuppe","source_url":null,"title":"Tomatensuppe","excerpt":"Cremige hausgemachte Tomatensuppe mit reifen Tomaten, Zwiebel, Knoblauch und frischem Basilikum. Für 4 Personen, fertig in 45 Minuten.","summary":"Für die Tomatensuppe werden Zwiebel und Knoblauch in Olivenöl angedünstet, die reifen Tomaten mit Gemüsebrühe gekocht und alles mit Basilikum zu einer glatten Creme püriert. Heiß servieren, mit Basilikumblättern und einem Schuss Olivenöl.\n\nDie Suppe braucht 45 Minuten für Vorbereitung und Garen. Ergibt 4 Portionen.","category":"Suppen und Cremesuppen","difficulty":"Einfach","course":"Vorspeise","cuisine":"International","prep_time_minutes":10,"cook_time_minutes":35,"total_time_minutes":45,"servings":4,"keywords":["Tomatensuppe","Tomatensuppe Rezept","Tomatensuppe selber machen","Tomatensuppe aus frischen Tomaten","Tomatencremesuppe","Tomatensuppe mit Basilikum","sopa de tomate"],"ingredients":[{"name":"reife Tomaten","amount":"1","unit":"kg","group":"Für die Suppe"},{"name":"Zwiebel","amount":"1","unit":"","group":"Für die Suppe"},{"name":"Knoblauchzehen","amount":"3","unit":"","group":"Für die Suppe"},{"name":"Olivenöl","amount":"3","unit":"Esslöffel","group":"Für die Suppe"},{"name":"Gemüsebrühe","amount":"500","unit":"ml","group":"Für die Suppe"},{"name":"frische Basilikumblätter","amount":"10","unit":"g","group":"Für die Suppe"},{"name":"Salz","amount":"1/2","unit":"Teelöffel","group":"Für die Suppe"},{"name":"schwarzer Pfeffer, gemahlen","amount":"1","unit":"Prise","group":"Für die Suppe"}],"steps":[{"title":"Zutaten vorbereiten","content":"1 kg Tomaten waschen und vierteln. 1 Zwiebel und 3 Knoblauchzehen fein hacken.","image_url":"/recetas/sopa-de-tomate/paso-01.webp","image_alt":"Tomatensuppe: Zutaten vorbereiten"},{"title":"Zwiebel und Knoblauch andünsten","content":"2 Esslöffel Olivenöl in einem Topf erhitzen und Zwiebel und Knoblauch 5 Minuten bei mittlerer Hitze andünsten, ohne dass sie Farbe nehmen.","image_url":"/recetas/sopa-de-tomate/paso-02.webp","image_alt":"Tomatensuppe: Zwiebel und Knoblauch andünsten"},{"title":"Tomaten zugeben","content":"Die Tomaten zugeben und 10 Minuten garen, dabei gelegentlich umrühren, bis sie zerfallen.","image_url":"/recetas/sopa-de-tomate/paso-03.webp","image_alt":"Tomatensuppe: Tomaten zugeben"},{"title":"Mit Brühe kochen","content":"500 ml Gemüsebrühe angießen und 15 Minuten bei mittlerer Hitze kochen.","image_url":"/recetas/sopa-de-tomate/paso-04.webp","image_alt":"Tomatensuppe: Mit Brühe kochen"},{"title":"Basilikum zugeben","content":"10 g frische Basilikumblätter zugeben und umrühren; einige Blätter zum Servieren beiseitelegen.","image_url":"/recetas/sopa-de-tomate/paso-05.webp","image_alt":"Tomatensuppe: Basilikum zugeben"},{"title":"Suppe pürieren","content":"Mit dem Stabmixer zu einer glatten Creme pürieren.","image_url":"/recetas/sopa-de-tomate/paso-06.webp","image_alt":"Tomatensuppe: Suppe pürieren"},{"title":"Abschmecken","content":"Die Suppe probieren, 1/2 Teelöffel Salz und 1 Prise Pfeffer zugeben und einige Sekunden weiter pürieren.","image_url":"/recetas/sopa-de-tomate/paso-07.webp","image_alt":"Tomatensuppe: Abschmecken"},{"title":"Servieren","content":"Heiß in tiefen Tellern servieren, mit Basilikumblättern und dem restlichen Esslöffel Olivenöl beträufelt.","image_url":"/recetas/sopa-de-tomate/paso-08.webp","image_alt":"Tomatensuppe: Servieren"}],"image_url":"/recetas/sopa-de-tomate/portada.webp","gallery":[{"url":"/recetas/sopa-de-tomate/portada.webp","alt":"Tomatensuppe"}],"notes":"Sehr reife Tomaten ergeben eine süßere Suppe mit kräftiger Farbe; sind sie sauer, beim Abschmecken eine Prise Zucker zugeben. Für eine feinere Konsistenz die Suppe nach dem Pürieren durch ein Sieb streichen. Sie hält sich bis zu 3 Tage im Kühlschrank und lässt sich bis zu 3 Monate einfrieren. Beim Aufwärmen etwas Brühe zugeben, falls sie eingedickt ist.","nutrition":{"calories":160,"protein_g":3.0,"carbs_g":15,"fat_g":10.8,"sodium_mg":265,"serving_size":"1 Portion (1/4 des Rezepts)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 4 Portionen geteilt. Verwendet werden 1 kg Tomaten, 150 g Zwiebel, 9 g Knoblauch, 40,5 g Olivenöl, 500 ml Gemüsebrühe und 10 g Basilikum. Zugefügtes Salz und Pfeffer werden nicht gezählt.","note":"Schätzung pro Portion. Die Gemüsebrühe wird mit ungefähren Werten einer handelsüblichen Brühe berechnet; ihr Natriumgehalt schwankt je nach Marke stark."},"seo":{"title":"Tomatensuppe selber machen, cremig und frisch | Manual de Cocina","description":"Cremige hausgemachte Tomatensuppe mit reifen Tomaten, Zwiebel, Knoblauch und frischem Basilikum. Für 4 Personen, fertig in 45 Minuten.","image_variants":["/recetas/sopa-de-tomate/portada-1x1.webp","/recetas/sopa-de-tomate/portada-4x3.webp","/recetas/sopa-de-tomate/portada-16x9.webp"],"faq":[{"q":"Kann ich Dosentomaten verwenden?","a":"Ja. Etwa 800 g ganze Dosentomaten mit Saft verwenden und die Garzeit der Tomaten auf 5 Minuten verkürzen."},{"q":"Wie wird die Suppe cremiger?","a":"Beim Pürieren 100 ml Sahne oder Milch zugeben oder eine kleine, in der Brühe gegarte Kartoffel mitpürieren."},{"q":"Kann man Tomatensuppe einfrieren?","a":"Ja, bis zu 3 Monate in einem luftdichten Behälter. Im Kühlschrank auftauen und bei schwacher Hitze erwärmen."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"bf2a6038-2c01-5375-bd3c-4a75c7224886","recipe_group_id":"6db1b18e-cc36-4cb2-9db5-cb87b6d815fe","language":"en","slug":"tomato-soup","public_path":"/en/tomato-soup","source_url":null,"title":"Tomato Soup","excerpt":"Creamy homemade tomato soup with ripe tomatoes, onion, garlic and fresh basil. Serves 4, ready in 45 minutes.","summary":"Tomato soup is made by softening onion and garlic in olive oil, simmering ripe tomatoes in vegetable broth and blending everything with basil into a smooth soup. Serve it hot with basil leaves and a drizzle of olive oil.\n\nThe soup takes 45 minutes from prep to table. It serves 4.","category":"Soups & creams","difficulty":"Easy","course":"Starter","cuisine":"International","prep_time_minutes":10,"cook_time_minutes":35,"total_time_minutes":45,"servings":4,"keywords":["tomato soup","tomato soup recipe","how to make tomato soup","homemade tomato soup","fresh tomato soup","tomato basil soup","sopa de tomate"],"ingredients":[{"name":"ripe tomatoes","amount":"1","unit":"kg","group":"For the soup"},{"name":"onion","amount":"1","unit":"","group":"For the soup"},{"name":"garlic cloves","amount":"3","unit":"","group":"For the soup"},{"name":"olive oil","amount":"3","unit":"tablespoon","group":"For the soup"},{"name":"vegetable broth","amount":"500","unit":"ml","group":"For the soup"},{"name":"fresh basil leaves","amount":"10","unit":"g","group":"For the soup"},{"name":"salt","amount":"1/2","unit":"teaspoon","group":"For the soup"},{"name":"ground black pepper","amount":"1","unit":"pinch","group":"For the soup"}],"steps":[{"title":"Prepare the ingredients","content":"Wash 1 kg tomatoes and cut them into quarters. Finely chop 1 onion and 3 garlic cloves.","image_url":"/recetas/sopa-de-tomate/paso-01.webp","image_alt":"Tomato Soup: Prepare the ingredients"},{"title":"Soften the onion and garlic","content":"Heat 2 tablespoons olive oil in a pot and cook the onion and garlic for 5 minutes over medium heat, without letting them brown.","image_url":"/recetas/sopa-de-tomate/paso-02.webp","image_alt":"Tomato Soup: Soften the onion and garlic"},{"title":"Add the tomatoes","content":"Add the tomatoes and cook for 10 minutes, stirring now and then, until they start to break down.","image_url":"/recetas/sopa-de-tomate/paso-03.webp","image_alt":"Tomato Soup: Add the tomatoes"},{"title":"Simmer with the broth","content":"Pour in 500 ml vegetable broth and simmer for 15 minutes over medium heat.","image_url":"/recetas/sopa-de-tomate/paso-04.webp","image_alt":"Tomato Soup: Simmer with the broth"},{"title":"Add the basil","content":"Add 10 g fresh basil leaves and stir; keep a few leaves for serving.","image_url":"/recetas/sopa-de-tomate/paso-05.webp","image_alt":"Tomato Soup: Add the basil"},{"title":"Blend the soup","content":"Blend with a hand blender until smooth.","image_url":"/recetas/sopa-de-tomate/paso-06.webp","image_alt":"Tomato Soup: Blend the soup"},{"title":"Season","content":"Taste the soup, add 1/2 teaspoon salt and 1 pinch pepper and blend for a few more seconds.","image_url":"/recetas/sopa-de-tomate/paso-07.webp","image_alt":"Tomato Soup: Season"},{"title":"Serve","content":"Serve hot in bowls with basil leaves and a drizzle of the remaining tablespoon of olive oil.","image_url":"/recetas/sopa-de-tomate/paso-08.webp","image_alt":"Tomato Soup: Serve"}],"image_url":"/recetas/sopa-de-tomate/portada.webp","gallery":[{"url":"/recetas/sopa-de-tomate/portada.webp","alt":"Tomato Soup"}],"notes":"Very ripe tomatoes give a sweeter soup with a deep color; if they are sharp, add a pinch of sugar when seasoning. For a silkier texture, pass the soup through a sieve after blending. It keeps up to 3 days in the fridge and can be frozen for up to 3 months. When reheating, add a little broth if it has thickened.","nutrition":{"calories":160,"protein_g":3.0,"carbs_g":15,"fat_g":10.8,"sodium_mg":265,"serving_size":"1 serving (1/4 of the recipe)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrients per 100 g multiplied by the weights of the ingredients and divided by 4 servings. It uses 1 kg tomatoes, 150 g onion, 9 g garlic, 40.5 g olive oil, 500 ml vegetable broth and 10 g basil. Added salt and pepper are not counted.","note":"Estimate per serving. The vegetable broth is calculated with approximate values for a store-bought broth; its sodium varies widely by brand."},"seo":{"title":"Homemade Tomato Soup, Creamy and Fresh | Manual de Cocina","description":"Creamy homemade tomato soup with ripe tomatoes, onion, garlic and fresh basil. Serves 4, ready in 45 minutes.","image_variants":["/recetas/sopa-de-tomate/portada-1x1.webp","/recetas/sopa-de-tomate/portada-4x3.webp","/recetas/sopa-de-tomate/portada-16x9.webp"],"faq":[{"q":"Can I use canned tomatoes?","a":"Yes. Use about 800 g canned whole tomatoes with their juice and cut the tomato cooking time to 5 minutes."},{"q":"How do I make the soup creamier?","a":"Add 100 ml cream or milk when blending, or blend in a small potato cooked in the broth."},{"q":"Can tomato soup be frozen?","a":"Yes, for up to 3 months in an airtight container. Thaw it in the fridge and reheat over low heat."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"f313eae8-95e4-5cf3-820d-0dd2bc68d16a","recipe_group_id":"6db1b18e-cc36-4cb2-9db5-cb87b6d815fe","language":"fr","slug":"soupe-de-tomates","public_path":"/fr/soupe-de-tomates","source_url":null,"title":"Soupe de tomates","excerpt":"Soupe de tomates maison et onctueuse, avec des tomates mûres, de l'oignon, de l'ail et du basilic frais. Pour 4 personnes, prête en 45 minutes.","summary":"La soupe de tomates se prépare en faisant revenir l'oignon et l'ail dans l'huile d'olive, en cuisant les tomates mûres avec du bouillon de légumes et en mixant le tout avec du basilic jusqu'à obtenir une soupe lisse. Elle se sert chaude avec des feuilles de basilic et un filet d'huile.\n\nLa soupe demande 45 minutes entre préparation et cuisson. Pour 4 portions.","category":"Soupes et crèmes","difficulty":"Facile","course":"Entrée","cuisine":"Internationale","prep_time_minutes":10,"cook_time_minutes":35,"total_time_minutes":45,"servings":4,"keywords":["soupe de tomates","recette soupe de tomates","comment faire une soupe de tomates","soupe de tomates maison","velouté de tomates","soupe de tomates au basilic","sopa de tomate"],"ingredients":[{"name":"tomates mûres","amount":"1","unit":"kg","group":"Pour la soupe"},{"name":"oignon","amount":"1","unit":"","group":"Pour la soupe"},{"name":"gousses d'ail","amount":"3","unit":"","group":"Pour la soupe"},{"name":"huile d'olive","amount":"3","unit":"cuillère à soupe","group":"Pour la soupe"},{"name":"bouillon de légumes","amount":"500","unit":"ml","group":"Pour la soupe"},{"name":"feuilles de basilic frais","amount":"10","unit":"g","group":"Pour la soupe"},{"name":"sel","amount":"1/2","unit":"cuillère à café","group":"Pour la soupe"},{"name":"poivre noir moulu","amount":"1","unit":"pincée","group":"Pour la soupe"}],"steps":[{"title":"Préparer les ingrédients","content":"Laver 1 kg de tomates et les couper en quartiers. Hacher finement 1 oignon et 3 gousses d'ail.","image_url":"/recetas/sopa-de-tomate/paso-01.webp","image_alt":"Soupe de tomates: Préparer les ingrédients"},{"title":"Faire revenir l'oignon et l'ail","content":"Chauffer 2 cuillères à soupe d'huile d'olive dans une casserole et faire revenir l'oignon et l'ail 5 minutes à feu moyen, sans les colorer.","image_url":"/recetas/sopa-de-tomate/paso-02.webp","image_alt":"Soupe de tomates: Faire revenir l'oignon et l'ail"},{"title":"Ajouter les tomates","content":"Ajouter les tomates et cuire 10 minutes en remuant de temps en temps, jusqu'à ce qu'elles commencent à se défaire.","image_url":"/recetas/sopa-de-tomate/paso-03.webp","image_alt":"Soupe de tomates: Ajouter les tomates"},{"title":"Cuire avec le bouillon","content":"Verser 500 ml de bouillon de légumes et cuire 15 minutes à feu moyen.","image_url":"/recetas/sopa-de-tomate/paso-04.webp","image_alt":"Soupe de tomates: Cuire avec le bouillon"},{"title":"Ajouter le basilic","content":"Ajouter 10 g de feuilles de basilic frais et remuer ; garder quelques feuilles pour servir.","image_url":"/recetas/sopa-de-tomate/paso-05.webp","image_alt":"Soupe de tomates: Ajouter le basilic"},{"title":"Mixer la soupe","content":"Mixer au mixeur plongeant jusqu'à obtenir une soupe lisse.","image_url":"/recetas/sopa-de-tomate/paso-06.webp","image_alt":"Soupe de tomates: Mixer la soupe"},{"title":"Rectifier l'assaisonnement","content":"Goûter la soupe, ajouter 1/2 cuillère à café de sel et 1 pincée de poivre et mixer encore quelques secondes.","image_url":"/recetas/sopa-de-tomate/paso-07.webp","image_alt":"Soupe de tomates: Rectifier l'assaisonnement"},{"title":"Servir","content":"Servir chaud dans des assiettes creuses, avec des feuilles de basilic et un filet de la cuillère d'huile d'olive restante.","image_url":"/recetas/sopa-de-tomate/paso-08.webp","image_alt":"Soupe de tomates: Servir"}],"image_url":"/recetas/sopa-de-tomate/portada.webp","gallery":[{"url":"/recetas/sopa-de-tomate/portada.webp","alt":"Soupe de tomates"}],"notes":"Des tomates bien mûres donnent une soupe plus douce et d'une couleur intense ; si elles sont acides, ajouter une pincée de sucre en rectifiant. Pour une texture plus fine, passer la soupe au tamis après l'avoir mixée. Elle se garde jusqu'à 3 jours au réfrigérateur et se congèle jusqu'à 3 mois. Au moment de réchauffer, ajouter un peu de bouillon si elle a épaissi.","nutrition":{"calories":160,"protein_g":3.0,"carbs_g":15,"fat_g":10.8,"sodium_mg":265,"serving_size":"1 portion (1/4 de la recette)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 4 portions. On utilise 1 kg de tomates, 150 g d'oignon, 9 g d'ail, 40,5 g d'huile d'olive, 500 ml de bouillon de légumes et 10 g de basilic. Le sel et le poivre ajoutés ne sont pas comptés.","note":"Estimation par portion. Le bouillon de légumes est calculé avec des valeurs approximatives d'un bouillon du commerce ; sa teneur en sodium varie beaucoup selon la marque."},"seo":{"title":"Soupe de tomates maison, onctueuse et fraîche | Manual de Cocina","description":"Soupe de tomates maison et onctueuse, avec des tomates mûres, de l'oignon, de l'ail et du basilic frais. Pour 4 personnes, prête en 45 minutes.","image_variants":["/recetas/sopa-de-tomate/portada-1x1.webp","/recetas/sopa-de-tomate/portada-4x3.webp","/recetas/sopa-de-tomate/portada-16x9.webp"],"faq":[{"q":"Puis-je utiliser des tomates en conserve ?","a":"Oui. Utiliser environ 800 g de tomates entières en conserve avec leur jus et réduire la cuisson des tomates à 5 minutes."},{"q":"Comment rendre la soupe plus onctueuse ?","a":"Ajouter 100 ml de crème ou de lait au moment de mixer, ou mixer avec une petite pomme de terre cuite dans le bouillon."},{"q":"Peut-on congeler la soupe de tomates ?","a":"Oui, jusqu'à 3 mois dans un récipient hermétique. La décongeler au réfrigérateur et la réchauffer à feu doux."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"4b2d37a0-75a4-55bc-b428-1f298fac04d7","recipe_group_id":"6db1b18e-cc36-4cb2-9db5-cb87b6d815fe","language":"it","slug":"zuppa-di-pomodoro","public_path":"/it/zuppa-di-pomodoro","source_url":null,"title":"Zuppa di pomodoro","excerpt":"Zuppa di pomodoro fatta in casa e cremosa, con pomodori maturi, cipolla, aglio e basilico fresco. Per 4 persone, pronta in 45 minuti.","summary":"La zuppa di pomodoro si prepara soffriggendo cipolla e aglio nell'olio d'oliva, cuocendo i pomodori maturi con brodo vegetale e frullando il tutto con il basilico fino a ottenere una crema liscia. Si serve calda con foglie di basilico e un filo d'olio.\n\nLa zuppa richiede 45 minuti tra preparazione e cottura. Per 4 porzioni.","category":"Zuppe e creme","difficulty":"Facile","course":"Antipasto","cuisine":"Internazionale","prep_time_minutes":10,"cook_time_minutes":35,"total_time_minutes":45,"servings":4,"keywords":["zuppa di pomodoro","ricetta zuppa di pomodoro","come fare la zuppa di pomodoro","zuppa di pomodoro fatta in casa","crema di pomodoro","zuppa di pomodoro al basilico","sopa de tomate"],"ingredients":[{"name":"pomodori maturi","amount":"1","unit":"kg","group":"Per la zuppa"},{"name":"cipolla","amount":"1","unit":"","group":"Per la zuppa"},{"name":"spicchi d'aglio","amount":"3","unit":"","group":"Per la zuppa"},{"name":"olio d'oliva","amount":"3","unit":"cucchiaio","group":"Per la zuppa"},{"name":"brodo vegetale","amount":"500","unit":"ml","group":"Per la zuppa"},{"name":"foglie di basilico fresco","amount":"10","unit":"g","group":"Per la zuppa"},{"name":"sale","amount":"1/2","unit":"cucchiaino","group":"Per la zuppa"},{"name":"pepe nero macinato","amount":"1","unit":"pizzico","group":"Per la zuppa"}],"steps":[{"title":"Prepara gli ingredienti","content":"Lava 1 kg di pomodori e tagliali in quarti. Trita finemente 1 cipolla e 3 spicchi d'aglio.","image_url":"/recetas/sopa-de-tomate/paso-01.webp","image_alt":"Zuppa di pomodoro: Prepara gli ingredienti"},{"title":"Soffriggi cipolla e aglio","content":"Scalda 2 cucchiai di olio d'oliva in una pentola e soffriggi cipolla e aglio per 5 minuti a fuoco medio, senza farli colorire.","image_url":"/recetas/sopa-de-tomate/paso-02.webp","image_alt":"Zuppa di pomodoro: Soffriggi cipolla e aglio"},{"title":"Aggiungi i pomodori","content":"Unisci i pomodori e cuocili per 10 minuti, mescolando di tanto in tanto, finché iniziano a disfarsi.","image_url":"/recetas/sopa-de-tomate/paso-03.webp","image_alt":"Zuppa di pomodoro: Aggiungi i pomodori"},{"title":"Cuoci con il brodo","content":"Versa 500 ml di brodo vegetale e cuoci per 15 minuti a fuoco medio.","image_url":"/recetas/sopa-de-tomate/paso-04.webp","image_alt":"Zuppa di pomodoro: Cuoci con il brodo"},{"title":"Aggiungi il basilico","content":"Aggiungi 10 g di foglie di basilico fresco e mescola; tieni da parte qualche foglia per servire.","image_url":"/recetas/sopa-de-tomate/paso-05.webp","image_alt":"Zuppa di pomodoro: Aggiungi il basilico"},{"title":"Frulla la zuppa","content":"Frulla con il frullatore a immersione fino a ottenere una crema liscia.","image_url":"/recetas/sopa-de-tomate/paso-06.webp","image_alt":"Zuppa di pomodoro: Frulla la zuppa"},{"title":"Regola di sapore","content":"Assaggia la zuppa, aggiungi 1/2 cucchiaino di sale e 1 pizzico di pepe e frulla ancora qualche secondo.","image_url":"/recetas/sopa-de-tomate/paso-07.webp","image_alt":"Zuppa di pomodoro: Regola di sapore"},{"title":"Servi","content":"Servi calda in piatti fondi, con foglie di basilico e un filo del cucchiaio di olio d'oliva rimasto.","image_url":"/recetas/sopa-de-tomate/paso-08.webp","image_alt":"Zuppa di pomodoro: Servi"}],"image_url":"/recetas/sopa-de-tomate/portada.webp","gallery":[{"url":"/recetas/sopa-de-tomate/portada.webp","alt":"Zuppa di pomodoro"}],"notes":"Pomodori ben maturi danno una zuppa più dolce e dal colore intenso; se sono acidi, aggiungi un pizzico di zucchero quando regoli di sapore. Per una consistenza più fine, passala al colino dopo averla frullata. Si conserva fino a 3 giorni in frigorifero e si può congelare fino a 3 mesi. Quando la riscaldi, aggiungi un po' di brodo se si è addensata.","nutrition":{"calories":160,"protein_g":3.0,"carbs_g":15,"fat_g":10.8,"sodium_mg":265,"serving_size":"1 porzione (1/4 della ricetta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g moltiplicati per i pesi degli ingredienti e divisi per 4 porzioni. Si usano 1 kg di pomodori, 150 g di cipolla, 9 g di aglio, 40,5 g di olio d'oliva, 500 ml di brodo vegetale e 10 g di basilico. Sale e pepe aggiunti non sono conteggiati.","note":"Stima per porzione. Il brodo vegetale è calcolato con valori approssimativi di un brodo confezionato; il suo contenuto di sodio varia molto a seconda della marca."},"seo":{"title":"Zuppa di pomodoro fatta in casa, cremosa e fresca | Manual de Cocina","description":"Zuppa di pomodoro fatta in casa e cremosa, con pomodori maturi, cipolla, aglio e basilico fresco. Per 4 persone, pronta in 45 minuti.","image_variants":["/recetas/sopa-de-tomate/portada-1x1.webp","/recetas/sopa-de-tomate/portada-4x3.webp","/recetas/sopa-de-tomate/portada-16x9.webp"],"faq":[{"q":"Posso usare i pomodori in scatola?","a":"Sì. Usa circa 800 g di pomodori pelati interi con il loro succo e riduci la cottura dei pomodori a 5 minuti."},{"q":"Come rendo la zuppa più cremosa?","a":"Aggiungi 100 ml di panna o latte quando la frulli, oppure frulla insieme una piccola patata cotta nel brodo."},{"q":"Si può congelare la zuppa di pomodoro?","a":"Sì, fino a 3 mesi in un contenitore ermetico. Scongelala in frigorifero e riscaldala a fuoco basso."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"d6df2dff-133d-59d5-94b9-864e943fea36","recipe_group_id":"6db1b18e-cc36-4cb2-9db5-cb87b6d815fe","language":"ja","slug":"トマトスープ","public_path":"/ja/トマトスープ","source_url":null,"title":"トマトスープ","excerpt":"完熟トマト、玉ねぎ、にんにく、生のバジルで作る、なめらかな手作りトマトスープ。4人分、45分で完成。","summary":"トマトスープは、玉ねぎとにんにくをオリーブオイルで炒め、完熟トマトを野菜ブイヨンで煮て、バジルと一緒になめらかになるまでミキサーにかけて作ります。バジルの葉とオリーブオイルを少したらして、温かいうちにいただきます。\n\n下ごしらえから調理まで45分かかります。4人分です。","category":"スープ・ポタージュ","difficulty":"簡単","course":"前菜","cuisine":"各国料理","prep_time_minutes":10,"cook_time_minutes":35,"total_time_minutes":45,"servings":4,"keywords":["トマトスープ","トマトスープ レシピ","トマトスープ 作り方","手作り トマトスープ","生トマト スープ","トマト バジル スープ","ソパ・デ・トマテ"],"ingredients":[{"name":"完熟トマト","amount":"1","unit":"kg","group":"スープ用"},{"name":"玉ねぎ","amount":"1","unit":"","group":"スープ用"},{"name":"にんにく","amount":"3","unit":"","group":"スープ用"},{"name":"オリーブオイル","amount":"3","unit":"大さじ","group":"スープ用"},{"name":"野菜ブイヨン","amount":"500","unit":"ml","group":"スープ用"},{"name":"バジルの葉（生）","amount":"10","unit":"g","group":"スープ用"},{"name":"塩","amount":"1/2","unit":"小さじ","group":"スープ用"},{"name":"黒こしょう（挽いたもの）","amount":"1","unit":"ひとつまみ","group":"スープ用"}],"steps":[{"title":"材料を準備する","content":"トマト1kgを洗って4つ割りにします。玉ねぎ1個とにんにく3片をみじん切りにします。","image_url":"/recetas/sopa-de-tomate/paso-01.webp","image_alt":"トマトスープ: 材料を準備する"},{"title":"玉ねぎとにんにくを炒める","content":"鍋にオリーブオイル大さじ2を熱し、玉ねぎとにんにくを中火で5分、色づかないように炒めます。","image_url":"/recetas/sopa-de-tomate/paso-02.webp","image_alt":"トマトスープ: 玉ねぎとにんにくを炒める"},{"title":"トマトを加える","content":"トマトを加え、ときどき混ぜながら、崩れ始めるまで10分煮ます。","image_url":"/recetas/sopa-de-tomate/paso-03.webp","image_alt":"トマトスープ: トマトを加える"},{"title":"ブイヨンで煮る","content":"野菜ブイヨン500mlを注ぎ、中火で15分煮ます。","image_url":"/recetas/sopa-de-tomate/paso-04.webp","image_alt":"トマトスープ: ブイヨンで煮る"},{"title":"バジルを加える","content":"バジルの葉10gを加えて混ぜます。盛り付け用に数枚取っておきます。","image_url":"/recetas/sopa-de-tomate/paso-05.webp","image_alt":"トマトスープ: バジルを加える"},{"title":"ミキサーにかける","content":"ハンドブレンダーでなめらかになるまで攪拌します。","image_url":"/recetas/sopa-de-tomate/paso-06.webp","image_alt":"トマトスープ: ミキサーにかける"},{"title":"味を調える","content":"味をみて、塩小さじ1/2とこしょうひとつまみを加え、さらに数秒攪拌してなじませます。","image_url":"/recetas/sopa-de-tomate/paso-07.webp","image_alt":"トマトスープ: 味を調える"},{"title":"盛り付ける","content":"温かいうちに深皿に盛り、バジルの葉をのせ、残りのオリーブオイル大さじ1をたらします。","image_url":"/recetas/sopa-de-tomate/paso-08.webp","image_alt":"トマトスープ: 盛り付ける"}],"image_url":"/recetas/sopa-de-tomate/portada.webp","gallery":[{"url":"/recetas/sopa-de-tomate/portada.webp","alt":"トマトスープ"}],"notes":"よく熟したトマトを使うと、甘みがあり色の濃いスープになります。酸味が強いときは、味を調えるときに砂糖をひとつまみ加えます。よりなめらかにしたいときは、攪拌したあとでこします。冷蔵庫で3日間、冷凍で3か月保存できます。温め直すときに濃くなっていたら、ブイヨンを少し足してください。","nutrition":{"calories":160,"protein_g":3.0,"carbs_g":15,"fat_g":10.8,"sodium_mg":265,"serving_size":"1人分（レシピの1/4）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養素に材料の重量を掛け、4人分で割って合計しています。トマト1kg、玉ねぎ150g、にんにく9g、オリーブオイル40.5g、野菜ブイヨン500ml、バジル10gを使用しています。加える塩とこしょうは計算に含めていません。","note":"1人分の目安です。野菜ブイヨンは市販品のおおよその値で計算しており、ナトリウム量は銘柄によって大きく異なります。"},"seo":{"title":"トマトスープの作り方｜手作りでなめらか | Manual de Cocina","description":"完熟トマト、玉ねぎ、にんにく、生のバジルで作る、なめらかな手作りトマトスープ。4人分、45分で完成。手順を写真付きで解説します。","image_variants":["/recetas/sopa-de-tomate/portada-1x1.webp","/recetas/sopa-de-tomate/portada-4x3.webp","/recetas/sopa-de-tomate/portada-16x9.webp"],"faq":[{"q":"トマト缶でも作れますか？","a":"作れます。ホールトマト缶約800gを汁ごと使い、トマトを煮る時間を5分に短くしてください。"},{"q":"もっとクリーミーにするには？","a":"攪拌するときに生クリームか牛乳を100ml加えるか、ブイヨンで煮た小さめのじゃがいもを一緒に攪拌します。"},{"q":"トマトスープは冷凍できますか？","a":"できます。密閉容器で3か月保存できます。冷蔵庫で解凍し、弱火で温め直してください。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"8a3a2be7-7b34-5161-aed7-f152cf9ee873","recipe_group_id":"6db1b18e-cc36-4cb2-9db5-cb87b6d815fe","language":"pt","slug":"sopa-de-tomate","public_path":"/pt/sopa-de-tomate","source_url":null,"title":"Sopa de tomate","excerpt":"Sopa de tomate caseira e cremosa, com tomates maduros, cebola, alho e manjericão fresco. Para 4 pessoas, pronta em 45 minutos.","summary":"A sopa de tomate é feita refogando cebola e alho no azeite, cozinhando os tomates maduros com caldo de legumes e batendo tudo com manjericão até obter um creme liso. É servida quente, com folhas de manjericão e um fio de azeite.\n\nA sopa leva 45 minutos entre preparo e cozimento. Rende 4 porções.","category":"Sopas e cremes","difficulty":"Fácil","course":"Entrada","cuisine":"Internacional","prep_time_minutes":10,"cook_time_minutes":35,"total_time_minutes":45,"servings":4,"keywords":["sopa de tomate","receita de sopa de tomate","como fazer sopa de tomate","sopa de tomate caseira","creme de tomate","sopa de tomate com manjericão","sopa de tomate natural"],"ingredients":[{"name":"tomates maduros","amount":"1","unit":"kg","group":"Para a sopa"},{"name":"cebola","amount":"1","unit":"","group":"Para a sopa"},{"name":"dentes de alho","amount":"3","unit":"","group":"Para a sopa"},{"name":"azeite","amount":"3","unit":"colher de sopa","group":"Para a sopa"},{"name":"caldo de legumes","amount":"500","unit":"ml","group":"Para a sopa"},{"name":"folhas de manjericão fresco","amount":"10","unit":"g","group":"Para a sopa"},{"name":"sal","amount":"1/2","unit":"colher de chá","group":"Para a sopa"},{"name":"pimenta-do-reino moída","amount":"1","unit":"pitada","group":"Para a sopa"}],"steps":[{"title":"Prepare os ingredientes","content":"Lave 1 kg de tomates e corte em quartos. Pique bem 1 cebola e 3 dentes de alho.","image_url":"/recetas/sopa-de-tomate/paso-01.webp","image_alt":"Sopa de tomate: Prepare os ingredientes"},{"title":"Refogue a cebola e o alho","content":"Aqueça 2 colheres de sopa de azeite em uma panela e refogue a cebola e o alho por 5 minutos em fogo médio, sem deixar dourar.","image_url":"/recetas/sopa-de-tomate/paso-02.webp","image_alt":"Sopa de tomate: Refogue a cebola e o alho"},{"title":"Junte os tomates","content":"Junte os tomates e cozinhe por 10 minutos, mexendo de vez em quando, até começarem a desmanchar.","image_url":"/recetas/sopa-de-tomate/paso-03.webp","image_alt":"Sopa de tomate: Junte os tomates"},{"title":"Cozinhe com o caldo","content":"Despeje 500 ml de caldo de legumes e cozinhe por 15 minutos em fogo médio.","image_url":"/recetas/sopa-de-tomate/paso-04.webp","image_alt":"Sopa de tomate: Cozinhe com o caldo"},{"title":"Junte o manjericão","content":"Junte 10 g de folhas de manjericão fresco e mexa; reserve algumas folhas para servir.","image_url":"/recetas/sopa-de-tomate/paso-05.webp","image_alt":"Sopa de tomate: Junte o manjericão"},{"title":"Bata a sopa","content":"Bata com o mixer até obter um creme liso.","image_url":"/recetas/sopa-de-tomate/paso-06.webp","image_alt":"Sopa de tomate: Bata a sopa"},{"title":"Acerte o tempero","content":"Prove a sopa, junte 1/2 colher de chá de sal e 1 pitada de pimenta e bata por mais alguns segundos.","image_url":"/recetas/sopa-de-tomate/paso-07.webp","image_alt":"Sopa de tomate: Acerte o tempero"},{"title":"Sirva","content":"Sirva quente em pratos fundos, com folhas de manjericão e um fio da colher de azeite restante.","image_url":"/recetas/sopa-de-tomate/paso-08.webp","image_alt":"Sopa de tomate: Sirva"}],"image_url":"/recetas/sopa-de-tomate/portada.webp","gallery":[{"url":"/recetas/sopa-de-tomate/portada.webp","alt":"Sopa de tomate"}],"notes":"Tomates bem maduros deixam a sopa mais doce e com cor intensa; se estiverem ácidos, junte uma pitada de açúcar ao acertar o tempero. Para uma textura mais fina, passe a sopa por uma peneira depois de bater. Conserva-se até 3 dias na geladeira e pode ser congelada por até 3 meses. Ao reaquecer, junte um pouco de caldo se tiver engrossado.","nutrition":{"calories":160,"protein_g":3.0,"carbs_g":15,"fat_g":10.8,"sodium_mg":265,"serving_size":"1 porção (1/4 da receita)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 4 porções. Usam-se 1 kg de tomates, 150 g de cebola, 9 g de alho, 40,5 g de azeite, 500 ml de caldo de legumes e 10 g de manjericão. O sal e a pimenta adicionados não são contados.","note":"Estimativa por porção. O caldo de legumes é calculado com valores aproximados de um caldo industrializado; o teor de sódio varia muito conforme a marca."},"seo":{"title":"Sopa de tomate caseira e cremosa | Manual de Cocina","description":"Sopa de tomate caseira e cremosa, com tomates maduros, cebola, alho e manjericão fresco. Para 4 pessoas, pronta em 45 minutos.","image_variants":["/recetas/sopa-de-tomate/portada-1x1.webp","/recetas/sopa-de-tomate/portada-4x3.webp","/recetas/sopa-de-tomate/portada-16x9.webp"],"faq":[{"q":"Posso usar tomate em lata?","a":"Pode. Use cerca de 800 g de tomate pelado inteiro em lata com o suco e reduza o cozimento dos tomates para 5 minutos."},{"q":"Como deixar a sopa mais cremosa?","a":"Junte 100 ml de creme de leite ou leite ao bater, ou bata junto uma batata pequena cozida no caldo."},{"q":"Dá para congelar a sopa de tomate?","a":"Dá, por até 3 meses em um pote hermético. Descongele na geladeira e reaqueça em fogo baixo."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/sopa-de-tomate') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
